[Form]
public class AVARUMConfigPartOf extends FormRun
{
    BOMId                   parentBOMId;
    BOM                     BOM;

}

public void init()
{
    BOM bomCur;

    if (element.args().caller())
    {
        if (classidget(element.args().caller()) == classnum(BOMDesignerCtrl))
        {
            if (element.args().record())
            {
                bomCur = element.args().record();
                parentBOMId = bomCur.BOMId;
                BOM = bomCur;
            }
        }
        else
        {
            parentBOMId = element.args().caller().BOMId();
        }
    }

    super();

    if (!parentBOMId)
    {
        element.close();
    }
}

public void fillTmpTable()
{
    AVARUMTmpConfigTable LocAVARUMTmpConfigTable;
    delete_from LocAVARUMTmpConfigTable;

    BOMVersion locBOMVersion;
    InventDimCombination locInventDimCombination;
    InventDim locInventDim;

    while select ItemId from locBOMVersion
        group by itemid
            where locBOMVersion.BOMId == parentBOMId
    {
        while select locInventDimCombination
                group by locInventDim.configId
                join locInventDim
                where locInventDimCombination.InventDimId==locInventDim.inventDimId
                  && locInventDimCombination.ItemId==locBOMVersion.itemid
        {
            LocAVARUMTmpConfigTable.clear();
            LocAVARUMTmpConfigTable.ItemId=locBOMVersion.ItemId;                
            LocAVARUMTmpConfigTable.ConfigId=locInventDim.configId;
            LocAVARUMTmpConfigTable.Chosen=false;
            LocAVARUMTmpConfigTable.ChosenConfigId='';
            LocAVARUMTmpConfigTable.ChosenItemId=BOM.ItemId;
            LocAVARUMTmpConfigTable.ChosenConfigGroupId=BOM.ConfigGroupId;

            ConfigChoice locConfigChoice;
            select firstonly * from locConfigChoice
                where locConfigChoice.ItemId==LocAVARUMTmpConfigTable.ItemId
                &&locConfigChoice.ConfigId==LocAVARUMTmpConfigTable.ConfigId
                &&locConfigChoice.ChosenItemId==LocAVARUMTmpConfigTable.ChosenItemId
                &&locConfigChoice.ChosenGroupId==LocAVARUMTmpConfigTable.ChosenConfigGroupId;
            if (locConfigChoice)
            {
                LocAVARUMTmpConfigTable.Chosen=true;
                LocAVARUMTmpConfigTable.ChosenConfigId=locConfigChoice.ChosenConfigId;                    
            }

            LocAVARUMTmpConfigTable.insert();
        }
    }
    AVARUMTmpConfigTable.setTmpData(LocAVARUMTmpConfigTable);
}

public void saveOne(AVARUMTmpConfigTable LocAVARUMTmpConfigTable)
{                
    ttsbegin;
    ConfigChoice locConfigChoice;
    select firstonly * from locConfigChoice
            where locConfigChoice.ItemId==LocAVARUMTmpConfigTable.ItemId
            &&locConfigChoice.ConfigId==LocAVARUMTmpConfigTable.ConfigId
            &&locConfigChoice.ChosenItemId==LocAVARUMTmpConfigTable.ChosenItemId;
    if (!LocAVARUMTmpConfigTable.Chosen || !LocAVARUMTmpConfigTable.ChosenConfigId)
    {
        if (locConfigChoice)
        {
            locConfigChoice.selectForUpdate(true);
            locConfigChoice.delete();
        }
    }
    else
    {
        if (!locConfigChoice)
        {
            locConfigChoice.ItemId=LocAVARUMTmpConfigTable.ItemId;
            locConfigChoice.ConfigId=LocAVARUMTmpConfigTable.ConfigId;
            locConfigChoice.ChosenItemId=LocAVARUMTmpConfigTable.ChosenItemId;
        }
        locConfigChoice.ChosenConfigId=LocAVARUMTmpConfigTable.ChosenConfigId;
        locConfigChoice.ChosenGroupId=LocAVARUMTmpConfigTable.ChosenConfigGroupId;
        locConfigChoice.write();
    }
    ttscommit;
}

/// <summary>
/// Set editable fields on active
/// </summary>
/// <returns>standard value</returns>
public int active()
{
    int ret;

    ret = super();

    boolean allowEdit;

    allowEdit = BOM.inventTable().configActive();

    AVARUMTmpConfigTable_ds.object(fieldNum(AVARUMTmpConfigTable, ChosenConfigId)).allowEdit(allowEdit);
    AVARUMTmpConfigTable_ds.object(fieldNum(AVARUMTmpConfigTable, ChosenConfigId)).skip(!allowEdit);

    return ret;
}

/// <summary>
/// Init tmp table on changed link record
/// </summary>
public void linkActive()
{
    BOM = element.args().record();
    super();

    element.fillTmpTable();
    AVARUMTmpConfigTable_ds.executeQuery();
}

/// <summary>
/// Sync saved data to table configChoice
/// </summary>
public void write()
{
    super();
    element.saveOne(AVARUMTmpConfigTable);
}

/// <summary>
/// Checks wheater combination Chosen and ChosenConfigId is correct
/// </summary>
/// <returns></returns>
public boolean validateWrite()
{
    boolean ret;

    ret = super();
    if (ret
        && AVARUMTmpConfigTable.Chosen
        && AVARUMTmpConfigTable.ChosenConfigId=='')
    {
        ret=checkFailed(strFmt("@SYS26332", fieldpname(AVARUMTmpConfigTable, ChosenConfigId)));
    }

    return ret;
}

/// <summary>
/// On deselect remove config id
/// </summary>
public void modified()
{
    super();
    if (!AVARUMTmpConfigTable.Chosen)
    {
        AVARUMTmpConfigTable.ChosenConfigId='';
    }
}

/// <summary>
/// Lookup to available variants
/// </summary>
/// <param name = "_formControl">config control</param>
/// <param name = "_filterStr">filterstr</param>
public void lookup(FormControl _formControl, str _filterStr)
{
    //super(_formControl, _filterStr);
    ConfigLookup::lookupConfigId(_formControl, bom.ItemId);
}
